    """L2 Relative Error: ||pred - target||_2 / ||target||_2."""
    diff = torch.norm(pred - target, p=2, dim=(-3, -2, -1))
    norm = torch.norm(target, p=2, dim=(-3, -2, -1))
    return (diff / (norm + 1e-8)).mean()


